body.script:
(function(){
  var frame = document.getElementById("static-scramjet-frame");
  var html = new TextDecoder().decode(Uint8Array.from(atob(""), function(c){ return c.charCodeAt(0); }));
  var params = new URLSearchParams(location.search);
  var inject = "<script>" +
    "window.__AETHER_STATIC_WISP=" + JSON.stringify(params.get("wisp") || "") + ";" +
    "window.__AETHER_STATIC_BACKEND=" + JSON.stringify(params.get("backend") || "scramjet2") + ";" +
    "window.__AETHER_STATIC_TARGET_HASH=" + JSON.stringify(location.hash.slice(1)) + ";" +
    "<\/script>";
  frame.srcdoc = html.replace("<head>", "<head>" + inject);
})();
